parameters.jsCode:
// Central configuration. Edit thresholds here or override via webhook body.
const incoming = $input.first() ? $input.first().json : {};
const body = (incoming && incoming.body) ? incoming.body : {};
const thresholds = {
  revenueDropPct: body.revenueDropPct != null ? Number(body.revenueDropPct) : 15,
  supportBacklogMax: body.supportBacklogMax != null ? Number(body.supportBacklogMax) : 50,
  pipelineTarget: body.pipelineTarget != null ? Number(body.pipelineTarget) : 500000,
  cashFlowMin: body.cashFlowMin != null ? Number(body.cashFlowMin) : 20000,
  baseCurrency: body.baseCurrency || "USD",
};
const fx = { USD: 1, EUR: 1.08, GBP: 1.27, NGN: 0.00065, KES: 0.0078 };
return [{ json: {
  runId: $execution.id,
  runMode: $execution.mode,
  triggeredAt: $now.toISO(),
  isWeekly: body.weekly != null ? Boolean(body.weekly) : ($now.weekday === 1 && $now.hour === 7),
  thresholds,
  fx,
} }];

const cfg = $("Load Config & Thresholds").first().json;
const fx = cfg.fx || { USD: 1 };
const base = (cfg.thresholds && cfg.thresholds.baseCurrency) || "USD";
function toBase(amount, cur) {
  const c = String(cur || base).toUpperCase();
  const rate = fx[c] != null ? fx[c] : 1;
  const n = Number(String(amount).replace(/[^0-9.\-]/g, ""));
  return isNaN(n) ? 0 : Math.round(n * rate);
}
function safeAll(name) { try { return $(name).all().map(i => i.json).filter(Boolean); } catch (e) { return []; } }

// --- Stripe (amounts are in cents) ---
const stripeRaw = safeAll("Fetch Stripe Payments");
const seen = {};
const payments = [];
for (const p of stripeRaw) {
  if (!p || !p.id || seen[p.id]) continue;
  seen[p.id] = true;
  if (p.status && p.status !== "succeeded") continue;
  payments.push({ id: p.id, amount: toBase((Number(p.amount) || 0) / 100, p.currency), currency: base, date: p.created ? new Date(p.created * 1000).toISOString() : null });
}

// --- HubSpot deals ---
const dealsRaw = safeAll("Fetch HubSpot Deals & Leads");
const deals = [];
for (const d of dealsRaw) {
  const pr = d && d.properties ? d.properties : {};
  deals.push({ id: d.id, stage: pr.dealstage || "unknown", amount: toBase(pr.amount || 0, base), createdate: pr.createdate || null });
}

// --- Jira tickets ---
const jiraRaw = safeAll("Fetch Jira Tickets");
const tickets = [];
for (const t of jiraRaw) {
  const f = t && t.fields ? t.fields : {};
  tickets.push({ key: t.key, status: (f.status && f.status.name) || "Unknown", priority: (f.priority && f.priority.name) || "None", created: f.created || null, resolved: f.resolutiondate || null });
}

// --- Marketing / Analytics ---
const ga = safeAll("Fetch Google Analytics")[0] || {};
   const marketing = { sessions: Number(ga.sessions) || 0, conversions: Number(ga.conversions) || 0, leads: deals.length, adSpend: toBase(ga.adSpend || 0, base) };

return [{ json: {
  meta: { runId: cfg.runId, triggeredAt: cfg.triggeredAt, isWeekly: cfg.isWeekly, baseCurrency: base },
  thresholds: cfg.thresholds,
  dataset: { payments, deals, tickets, marketing },
  counts: { payments: payments.length, deals: deals.length, tickets: tickets.length },
} }];

const src = $input.first().json;
const d = src.dataset;
const now = new Date();
const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);

// Sales
const totalRevenue = d.payments.reduce((s, p) => s + (p.amount || 0), 0);
const monthlyRevenue = d.payments.filter(p => p.date && new Date(p.date) >= monthStart).reduce((s, p) => s + p.amount, 0);
const won = d.deals.filter(x => x.stage === "closedwon");
const lost = d.deals.filter(x => x.stage === "closedlost");
const openDeals = d.deals.filter(x => x.stage !== "closedwon" && x.stage !== "closedlost");
const pipelineValue = openDeals.reduce((s, x) => s + (x.amount || 0), 0);
const closedDeals = won.length;
const winRate = (won.length + lost.length) > 0 ? Math.round((won.length / (won.length + lost.length)) * 100) : 0;

// Marketing
const leads = d.marketing.leads;
const costPerLead = leads > 0 ? Math.round(d.marketing.adSpend / leads) : 0;
const conversionRate = d.marketing.sessions > 0 ? Math.round((d.marketing.conversions / d.marketing.sessions) * 1000) / 10 : 0;

// Operations / Support
const openTickets = d.tickets.filter(t => t.status !== "Done" && t.status !== "Closed");
const resolved = d.tickets.filter(t => t.resolved);
let avgResolutionHrs = 0;
if (resolved.length) {
  const totalHrs = resolved.reduce((s, t) => s + ((new Date(t.resolved) - new Date(t.created)) / 3600000), 0);
  avgResolutionHrs = Math.round(totalHrs / resolved.length);
}
const escalations = d.tickets.filter(t => t.priority === "Critical" || t.priority === "High").length;
const escalationRate = d.tickets.length ? Math.round((escalations / d.tickets.length) * 100) : 0;

// Finance (illustrative from available signals)
const monthlyExpenses = d.marketing.adSpend;
const cashFlow = monthlyRevenue - monthlyExpenses;
const profitMargin = monthlyRevenue > 0 ? Math.round((cashFlow / monthlyRevenue) * 100) : 0;

const kpis = {
  sales: { totalRevenue, monthlyRevenue, pipelineValue, closedDeals, winRate },
  marketing: { leads, costPerLead, conversionRate, sessions: d.marketing.sessions },
  operations: { activeProjects: openDeals.length, openTickets: openTickets.length, workflowSuccessRate: 100 },
  finance: { outstandingInvoices: pipelineValue, cashFlow, monthlyExpenses, profitMargin },
  support: { openTickets: openTickets.length, avgResolutionHrs, escalationRate, escalations },
};
return [{ json: { meta: src.meta, thresholds: src.thresholds, counts: src.counts, kpis } }];

const kpiItem = $("Calculate KPIs").first().json;
const kpis = kpiItem.kpis;
const th = kpiItem.thresholds || {};
const meta = kpiItem.meta;
// AI structured output (json_schema => already an object)
   let ai = {};
   try {
     const msg = ($json.output || []).find(o => o.type === "message");
     ai = msg.content[0].text;
   } catch (e) { ai = {}; }
if (typeof ai === "string") { try { ai = JSON.parse(ai); } catch (e) { ai = {}; } }

const alerts = [];
if (kpis.support.openTickets > (th.supportBacklogMax || 50)) {
  alerts.push({ severity: "high", area: "Operations", audience: "Operations Manager", message: "Support backlog " + kpis.support.openTickets + " exceeds threshold " + (th.supportBacklogMax || 50) });
}
if (kpis.sales.pipelineValue < (th.pipelineTarget || 500000)) {
  alerts.push({ severity: "high", area: "Sales", audience: "Sales Leadership", message: "Pipeline " + kpis.sales.pipelineValue + " below target " + (th.pipelineTarget || 500000) });
}
if (kpis.finance.cashFlow < (th.cashFlowMin || 20000)) {
  alerts.push({ severity: "critical", area: "Finance", audience: "Finance", message: "Cash flow " + kpis.finance.cashFlow + " below minimum " + (th.cashFlowMin || 20000) });
}
if (kpis.support.escalationRate > 30) {
  alerts.push({ severity: "medium", area: "Support", audience: "Support Lead", message: "Escalation rate " + kpis.support.escalationRate + "% is elevated" });
}

return [{ json: {
  meta, thresholds: th, kpis, ai,
  alerts,
  hasHighPriority: alerts.some(a => a.severity === "high" || a.severity === "critical"),
  generatedAt: $now.toISO(),
} }];

const s = $input.first().json;
const k = s.kpis;
const dashboards = {
  sales: k.sales,
  marketing: k.marketing,
  finance: k.finance,
  operations: k.operations,
  support: k.support,
  companyOverview: {
    revenue: k.sales.totalRevenue,
    pipeline: k.sales.pipelineValue,
    cashFlow: k.finance.cashFlow,
    openTickets: k.support.openTickets,
    leads: k.marketing.leads,
    alerts: s.alerts.length,
    generatedAt: s.generatedAt,
  },
};
return [{ json: { runId: s.meta.runId, generatedAt: s.generatedAt, dashboards } }];

const s = $input.first().json;
const k = s.kpis;
const ai = s.ai || {};
const LF = String.fromCharCode(10);
function list(arr) {
  if (!arr || !arr.length) return "<li>None</li>";
  return arr.map(x => "<li>" + x + "</li>").join(LF);
}
const rows = [
  "<h1>Executive Business Report</h1>",
  "<p><em>Generated " + s.generatedAt + "</em></p>",
  "<h2>Executive Summary</h2><p>" + (ai.executive_summary || "N/A") + "</p>",
  "<h2>KPI Overview</h2>",
  "<ul>",
  "<li>Total Revenue: " + k.sales.totalRevenue + "</li>",
  "<li>Monthly Revenue: " + k.sales.monthlyRevenue + "</li>",
  "<li>Pipeline Value: " + k.sales.pipelineValue + "</li>",
  "<li>Win Rate: " + k.sales.winRate + "%</li>",
  "<li>Leads: " + k.marketing.leads + " | Cost/Lead: " + k.marketing.costPerLead + "</li>",
  "<li>Cash Flow: " + k.finance.cashFlow + " | Profit Margin: " + k.finance.profitMargin + "%</li>",
  "<li>Open Tickets: " + k.support.openTickets + " | Escalation Rate: " + k.support.escalationRate + "%</li>",
  "</ul>",
  "<h2>Performance Analysis</h2><p>" + (ai.performance_analysis || "N/A") + "</p>",
  "<h2>Major Risks</h2><ul>" + list(ai.risks) + "</ul>",
  "<h2>Opportunities</h2><ul>" + list(ai.opportunities) + "</ul>",
  "<h2>Action Items</h2><ul>" + list(ai.recommended_actions) + "</ul>",
  "<h2>AI Recommendations & Bottlenecks</h2><ul>" + list(ai.bottlenecks) + "</ul>",
  "<h2>Active Alerts</h2><ul>" + list(s.alerts.map(a => a.severity.toUpperCase() + " - " + a.area + ": " + a.message)) + "</ul>",
];
const reportHtml = "<div style=\"font-family:Arial,sans-serif\">" + rows.join(LF) + "</div>";
return [{ json: { runId: s.meta.runId, subject: "Weekly Executive Report - " + s.generatedAt, reportHtml } }];

const s = $input.first().json;
const LF = String.fromCharCode(10);
const lines = s.alerts.map(a => "*" + a.severity.toUpperCase() + "* [" + a.area + " -> " + a.audience + "] " + a.message);
const text = ":rotating_light: *Executive Alerts* (" + s.alerts.length + ")" + LF + lines.join(LF);
return [{ json: { text, alerts: s.alerts, kpis: s.kpis, ai: s.ai, generatedAt: s.generatedAt } }];

